fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since `arr` is non-empty, we can safely iterate over adjacent pairs.
    // If any adjacent pair is out of order, return false immediately.
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    // If we never found a violation, the array is sorted.
    true
}

